export class SearchIndex{constructor(){this.nameIndex=new Map,this.clanIndex=new Map,this.rankIndex=new Map,this.prefixIndex=new Map}addProfile(e){const t=e.playerName;e.realName&&this.nameIndex.set(e.realName.toLowerCase(),t),e.customName&&this.nameIndex.set(e.customName.toLowerCase(),t),e.clan&&this._addToSetIndex(this.clanIndex,e.clan.toLowerCase(),t),e.rank&&this._addToSetIndex(this.rankIndex,e.rank.toLowerCase(),t),this._addPrefixes(e.realName||e.playerName,t),e.customName&&this._addPrefixes(e.customName,t)}removeProfile(e){const t=e.playerName;e.realName&&this.nameIndex.delete(e.realName.toLowerCase()),e.customName&&this.nameIndex.delete(e.customName.toLowerCase()),e.clan&&this._removeFromSetIndex(this.clanIndex,e.clan.toLowerCase(),t),e.rank&&this._removeFromSetIndex(this.rankIndex,e.rank.toLowerCase(),t),this._removePrefixes(e.realName||e.playerName,t),e.customName&&this._removePrefixes(e.customName,t)}updateProfile(e,t){e&&this.removeProfile(e),this.addProfile(t)}findExact(e){return this.nameIndex.get(e.toLowerCase())}findByPrefix(e){const t=e.toLowerCase(),s=new Set;for(const[e,n]of this.prefixIndex)if(e.startsWith(t))for(const e of n)s.add(e);return Array.from(s)}findByClan(e){const t=this.clanIndex.get(e.toLowerCase());return t?Array.from(t):[]}findByRank(e){const t=this.rankIndex.get(e.toLowerCase());return t?Array.from(t):[]}search(e,t=50){const s=e.toLowerCase(),n=new Set,r=this.findExact(s);r&&n.add(r);const a=this.findByPrefix(s);for(const e of a.slice(0,t-n.size))n.add(e);const o=this.findByClan(s);for(const e of o.slice(0,t-n.size))n.add(e);const i=this.findByRank(s);for(const e of i.slice(0,t-n.size))n.add(e);return Array.from(n).slice(0,t)}_addPrefixes(e,t){if(!e)return;const s=e.toLowerCase();for(let e=2;e<=s.length;e++){const n=s.substring(0,e);this._addToSetIndex(this.prefixIndex,n,t)}}_removePrefixes(e,t){if(!e)return;const s=e.toLowerCase();for(let e=2;e<=s.length;e++){const n=s.substring(0,e);this._removeFromSetIndex(this.prefixIndex,n,t)}}_addToSetIndex(e,t,s){e.has(t)||e.set(t,new Set),e.get(t).add(s)}_removeFromSetIndex(e,t,s){const n=e.get(t);n&&(n.delete(s),0===n.size&&e.delete(t))}getStats(){return{nameEntries:this.nameIndex.size,clanEntries:this.clanIndex.size,rankEntries:this.rankIndex.size,prefixEntries:this.prefixIndex.size,totalMemory:this._estimateMemoryUsage()}}_estimateMemoryUsage(){let e=0;e+=50*this.nameIndex.size;for(const t of this.clanIndex.values())e+=30*t.size;for(const t of this.rankIndex.values())e+=30*t.size;for(const t of this.prefixIndex.values())e+=30*t.size;return e}clear(){this.nameIndex.clear(),this.clanIndex.clear(),this.rankIndex.clear(),this.prefixIndex.clear()}}